251→+//! Recycle bin metadata types and encryption.
252→+//!
253→+//! Mirrors the TypeScript `RecycleBinMetadata` and `BinEntry` types from
254→+//! `@cipherbox/crypto` for cross-platform compatibility. Uses ECIES
255→+//! (same as DeviceRegistry) for encryption -- the user's secp256k1
256→+//! publicKey encrypts, privateKey decrypts.
257→+
258→+use serde::{Deserialize, Serialize};
259→+use thiserror::Error;
260→+
261→+use super::folder::{FilePointer, FolderEntry};
262→+
263→+#[derive(Debug, Error)]
264→+pub enum BinError {
265→+    #[error("Bin metadata encryption failed")]
266→+    EncryptionFailed,
267→+    #[error("Bin metadata decryption failed")]
268→+    DecryptionFailed,
269→+    #[error("Bin metadata serialization failed")]
270→+    SerializationFailed,
271→+    #[error("Bin metadata deserialization failed")]
272→+    DeserializationFailed,
273→+    #[error("Bin metadata validation failed: {0}")]
274→+    ValidationFailed(String),
275→+}
276→+
277→+/// Top-level recycle bin metadata structure.
278→+/// Encrypted as a whole blob via ECIES with the user's secp256k1 publicKey.
279→+#[derive(Debug, Clone, Serialize, Deserialize)]
280→+#[serde(rename_all = "camelCase")]
281→+pub struct RecycleBinMetadata {
282→+    pub version: String,
283→+    pub sequence_number: u64,
284→+    pub entries: Vec<BinEntry>,
285→+}
286→+
287→+/// A single item in the recycle bin.
288→+#[derive(Debug, Clone, Serialize, Deserialize)]
289→+#[serde(rename_all = "camelCase")]
290→+pub struct BinEntry {
291→+    pub id: String,
292→+    pub item_type: BinItemType,
293→+    pub name: String,
294→+    pub original_parent_ipns_name: String,
295→+    pub original_path: String,
296→+    pub deleted_at: u64,
297→+    pub size: u64,
298→+    pub mime_type: String,
299→+    #[serde(skip_serializing_if = "Option::is_none")]
300→+    #[serde(default)]
301→+    pub file_pointer: Option<FilePointer>,
302→+    #[serde(skip_serializing_if = "Option::is_none")]
303→+    #[serde(default)]
304→+    pub folder_entry: Option<FolderEntry>,
305→+}
306→+
307→+#[derive(Debug, Clone, Serialize, Deserialize)]
308→+#[serde(rename_all = "lowercase")]
309→+pub enum BinItemType {
310→+    File,
311→+    Folder,
312→+}
313→+
314→+/// Encrypt bin metadata with ECIES using user's secp256k1 public key.
315→+///
316→+/// JSON-serializes the metadata, then encrypts the entire blob with ECIES.
317→+/// Cross-compatible with TypeScript `encryptBinMetadata` from @cipherbox/crypto.
318→+pub fn encrypt_bin_metadata(
319→+    metadata: &RecycleBinMetadata,
320→+    user_public_key: &[u8],
321→+) -> Result<Vec<u8>, BinError> {
322→+    let json = serde_json::to_vec(metadata)
323→+        .map_err(|_| BinError::SerializationFailed)?;
324→+    crate::crypto::ecies::wrap_key(&json, user_public_key)
325→+        .map_err(|_| BinError::EncryptionFailed)
326→+}
327→+
328→+/// Decrypt bin metadata with ECIES using user's secp256k1 private key.
329→+pub fn decrypt_bin_metadata(
330→+    ciphertext: &[u8],
331→+    user_private_key: &[u8],
332→+) -> Result<RecycleBinMetadata, BinError> {
333→+    let plaintext = crate::crypto::ecies::unwrap_key(ciphertext, user_private_key)
334→+        .map_err(|_| BinError::DecryptionFailed)?;
335→+    let metadata: RecycleBinMetadata = serde_json::from_slice(&plaintext)
336→+        .map_err(|_| BinError::DeserializationFailed)?;
337→+    if metadata.version != "v1" {
338→+        return Err(BinError::ValidationFailed(
339→+            format!("Unsupported bin metadata version: {}", metadata.version),
340→+        ));
341→+    }
342→+    Ok(metadata)
343→+}
344→+
345→+/// Create a new empty RecycleBinMetadata.
346→+pub fn empty_bin_metadata() -> RecycleBinMetadata {
347→+    RecycleBinMetadata {
348→+        version: "v1".to_string(),
349→+        sequence_number: 0,
350→+        entries: vec![],
351→+    }
352→+}
