354→+/// Generate a random UUID v4 string.
355→+/// Uses the same pattern as `registry/mod.rs::generate_uuid_v4`.
356→+pub fn generate_uuid_v4() -> String {
357→+    let bytes = crate::crypto::utils::generate_random_bytes(16);
358→+    format!(
359→+        "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-4{:01x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
360→+        bytes[0], bytes[1], bytes[2], bytes[3],
361→+        bytes[4], bytes[5],
362→+        bytes[6] & 0x0f, bytes[7],
363→+        (bytes[8] & 0x3f) | 0x80, bytes[9],
364→+        bytes[10], bytes[11], bytes[12], bytes[13], bytes[14], bytes[15],
365→+    )
366→+}
