378→            <div className="bin-column-header bin-column-path" role="columnheader">
379→              [LOCATION]
380→            </div>
381→            <button
382→              type="button"
383→              className="bin-column-header bin-column-deleted"
384→              onClick={() => handleSortClick('deletedAt')}
385→              role="columnheader"
386→              aria-sort={
387→                sortField === 'deletedAt'
388→                  ? sortDirection === 'asc'
389→                    ? 'ascending'
390→                    : 'descending'
391→                  : 'none'
392→              }
393→            >
