  1→/**
  2→ * BinBrowser -- Recycle bin browser with flat list of deleted items.
  3→ *
  4→ * Shows all soft-deleted files and folders in a flat list sorted by deletion date.
  5→ * Supports restore, permanent delete, batch operations, and Empty Bin.
  6→ * Auto-purges expired items on mount.
  7→ */
  8→
  9→import { useState, useCallback, useEffect, useRef, useMemo, type MouseEvent } from 'react';
 10→import type { BinEntry } from '@cipherbox/crypto';
 11→import { useBin } from '../../hooks/useBin';
