 22→    entries,
 23→    isLoading,
 24→    isLoaded,
 25→    error,
 26→    retentionDays,
 27→    daysRemaining,
 28→    loadBin,
 29→    restore,
 30→    permanentDelete,
 31→    emptyAll,
 32→    restoreMultiple,
 33→    permanentDeleteMultiple,
 34→    isLoading: isOperating,
