 75→      return pruned;
 76→    });
 77→  }, [entryIds]);
 78→
 79→  // Sort entries
 80→  const sortedEntries = useMemo(() => {
 81→    const sorted = [...entries].sort((a, b) => {
 82→      let cmp = 0;
