1942→+/**
1943→+ * Format a deletion timestamp as a relative time string.
1944→+ */
1945→+function formatRelativeTime(timestamp: number): string {
1946→+  const diff = Date.now() - timestamp;
1947→+  const seconds = Math.floor(diff / 1000);
1948→+  const minutes = Math.floor(seconds / 60);
1949→+  const hours = Math.floor(minutes / 60);
1950→+  const days = Math.floor(hours / 24);
1951→+
1952→+  if (seconds < 60) return 'just now';
1953→+  if (minutes < 60) return `${minutes}m ago`;
1954→+  if (hours < 24) return `${hours}h ago`;
1955→+  if (days === 1) return '1 day ago';
1956→+  return `${days} days ago`;
1957→+}
