1965→+  if (entry.mimeType.startsWith('image/')) return '[IMG]';
1966→+  if (entry.mimeType.startsWith('video/')) return '[VID]';
1967→+  if (entry.mimeType.startsWith('audio/')) return '[AUD]';
1968→+  if (entry.mimeType.startsWith('text/')) return '[TXT]';
1969→+  if (entry.mimeType === 'application/pdf') return '[PDF]';
