2723→+// ---------------------------------------------------------------------------
2724→+// Public API: initializeBin
2725→+// ---------------------------------------------------------------------------
2726→+
2727→+/**
2728→+ * Initialize or load the recycle bin on login.
2729→+ *
2730→+ * Derives the deterministic IPNS keypair, resolves existing bin metadata
2731→+ * from IPNS (or creates empty state), and populates the bin store.
2732→+ *
2733→+ * Non-blocking: errors are logged, not thrown.
2734→+ */
2735→+export async function initializeBin(params: {
2736→+  userPrivateKey: Uint8Array;
2737→+  userPublicKey: Uint8Array;
2738→+}): Promise<void> {
2739→+  const store = useBinStore.getState();
2740→+  store.setLoading(true);
2741→+
2742→+  try {
2743→+    // Reset TEE enrollment tracking for new session
2744→+    binTeeEnrolled = false;
2745→+
2746→+    const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
2747→+    store.setBinIpnsName(binIpns.ipnsName);
2748→+
2749→+    // Try to load existing bin metadata
2750→+    const loaded = await loadBinMetadata({ userPrivateKey: params.userPrivateKey });
2751→+
2752→+    if (loaded) {
2753→+      store.setEntries(loaded.metadata.entries, loaded.metadata.sequenceNumber);
2754→+    } else {
2755→+      // No bin exists yet -- initialize with empty state
2756→+      store.setEntries([], 0);
2757→+    }
2758→+  } catch (error) {
2759→+    console.error('[Bin] Failed to initialize bin:', error);
2760→+    store.setError(error instanceof Error ? error.message : 'Failed to initialize bin');
2761→+    store.setLoading(false);
2762→+  }
2763→+}
2764→+
2765→+// ---------------------------------------------------------------------------
2766→+// Public API: addToBin
2767→+// ---------------------------------------------------------------------------
2768→+
2769→+/**
2770→+ * Add a deleted item to the recycle bin.
2771→+ *
2772→+ * Creates a BinEntry from the FolderChild that was removed from its parent,
2773→+ * appends it to the bin metadata, encrypts, and publishes.
2774→+ *
2775→+ * @param params.item - The FolderChild (FilePointer or FolderEntry) that was removed
2776→+ * @param params.parentIpnsName - IPNS name of the original parent folder
2777→+ * @param params.parentPath - Breadcrumb path at deletion time (e.g., "My Vault / Documents")
2778→+ * @param params.userPublicKey - User's secp256k1 public key for ECIES encryption
2779→+ * @param params.userPrivateKey - User's secp256k1 private key for IPNS derivation
2780→+ */
2781→+export async function addToBin(params: {
2782→+  item: FolderChild;
2783→+  parentIpnsName: string;
2784→+  parentPath: string;
2785→+  userPublicKey: Uint8Array;
2786→+  userPrivateKey: Uint8Array;
2787→+}): Promise<void> {
2788→+  const { item, parentIpnsName, parentPath, userPublicKey, userPrivateKey } = params;
2789→+
2790→+  // Build bin entry
2791→+  const isFile = item.type === 'file';
2792→+  const entry: BinEntry = {
2793→+    id: crypto.randomUUID(),
2794→+    itemType: isFile ? 'file' : 'folder',
2795→+    name: item.name,
2796→+    originalParentIpnsName: parentIpnsName,
2797→+    originalPath: parentPath,
2798→+    deletedAt: Date.now(),
2799→+    size: 0, // Files: resolved lazily on permanent delete. Folders: 0.
2800→+    mimeType: '',
2801→+    filePointer: isFile ? (item as FilePointer) : undefined,
2802→+    folderEntry: !isFile ? (item as FolderEntry) : undefined,
2803→+  };
2804→+
2805→+  // Read current bin state and build updated metadata
2806→+  const store = useBinStore.getState();
2807→+  const currentEntries = [...store.entries, entry];
2808→+  const newSeq = store.sequenceNumber + 1;
2809→+
2810→+  const metadata: RecycleBinMetadata = {
2811→+    version: 'v1',
2812→+    sequenceNumber: newSeq,
2813→+    entries: currentEntries,
2814→+  };
2815→+
2816→+  // Encrypt and publish
2817→+  await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
2818→+
2819→+  // Update local store
2820→+  store.addEntry(entry);
