2836→+  entryId: string;
2837→+  userPublicKey: Uint8Array;
2838→+  userPrivateKey: Uint8Array;
2839→+}): Promise<void> {
2840→+  const { entryId, userPublicKey, userPrivateKey } = params;
2841→+
2842→+  const binStore = useBinStore.getState();
2843→+  const entry = binStore.entries.find((e) => e.id === entryId);
2844→+  if (!entry) throw new Error('Bin entry not found');
2845→+
