2862→+    folderId: targetFolder.id,
2863→+    children: updatedChildren,
2864→+    folderKey: targetFolder.folderKey,
2865→+    ipnsPrivateKey: targetFolder.ipnsPrivateKey,
2866→+    ipnsName: targetFolder.ipnsName,
2867→+    sequenceNumber: targetFolder.sequenceNumber,
2868→+  });
2869→+
2870→+  // Update folder store
2871→+  const folderStore = useFolderStore.getState();
2872→+  folderStore.updateFolderChildren(targetFolder.id, updatedChildren);
2873→+  folderStore.updateFolderSequence(targetFolder.id, newSequenceNumber);
