249→    /// Delete a file from a directory.
250→    pub fn handle_unlink(
251→        fs: &mut CipherBoxFS,
252→        parent: u64,
253→        name: &OsStr,
254→        reply: ReplyEmpty,
255→    ) {
256→        let name_str = match name.to_str() {
257→            Some(n) => n,
258→            None => {
259→                reply.error(libc::ENOENT);
260→                return;
261→            }
262→        };
263→
264→        let child_ino = match fs.inodes.find_child(parent, name_str) {
265→            Some(ino) => ino,
266→            None => {
267→                reply.error(libc::ENOENT);
268→                return;
269→            }
270→        };
271→
272→        // Capture data for bin entry before inode removal
273→        let bin_entry_data = match fs.inodes.get(child_ino) {
274→            Some(inode) => match &inode.kind {
275→                InodeKind::File {
276→                    file_meta_ipns_name,
277→                    file_ipns_key_encrypted_hex,
278→                    size,
279→                    ..
280→                } => {
281→                    let now_ms = SystemTime::now()
282→                        .duration_since(std::time::UNIX_EPOCH)
283→                        .unwrap_or_default()
284→                        .as_millis() as u64;
285→                    let created_ms = inode.attr.crtime
286→                        .duration_since(std::time::UNIX_EPOCH)
287→                        .unwrap_or_default()
288→                        .as_millis() as u64;
289→
290→                    let file_pointer = crate::crypto::folder::FilePointer {
291→                        id: crate::crypto::bin::generate_uuid_v4(),
292→                        name: inode.name.clone(),
293→                        file_meta_ipns_name: file_meta_ipns_name.clone().unwrap_or_default(),
294→                        ipns_private_key_encrypted: file_ipns_key_encrypted_hex.clone(),
295→                        created_at: if created_ms > 0 { created_ms } else { now_ms },
296→                        modified_at: now_ms,
297→                    };
298→
299→                    Some((inode.name.clone(), *size, file_pointer))
300→                }
301→                _ => {
302→                    reply.error(libc::EISDIR);
303→                    return;
304→                }
305→            },
306→            None => {
307→                reply.error(libc::ENOENT);
308→                return;
309→            }
310→        };
311→
312→        log::debug!("unlink: {} from parent {}", name_str, parent);
313→
314→        fs.inodes.remove(child_ino);
315→
316→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
317→            parent_inode.attr.mtime = SystemTime::now();
318→            parent_inode.attr.ctime = SystemTime::now();
319→        }
320→
321→        if let Err(e) = fs.update_folder_metadata(parent) {
322→            log::error!("Failed to update folder metadata after unlink: {}", e);
323→        }
324→
325→        // Create bin entry and publish to bin IPNS (fire-and-forget)
326→        if let Some((item_name, file_size, file_pointer)) = bin_entry_data {
327→            let parent_ipns_name = fs.inodes.get(parent)
328→                .map(|p| match &p.kind {
329→                    InodeKind::Root { ipns_name, .. } => ipns_name.clone().unwrap_or_default(),
330→                    InodeKind::Folder { ipns_name, .. } => ipns_name.clone(),
331→                    _ => String::new(),
332→                })
333→                .unwrap_or_default();
334→
335→            let parent_path = build_folder_path(fs, parent);
336→
337→            let bin_entry = crate::crypto::bin::BinEntry {
338→                id: crate::crypto::bin::generate_uuid_v4(),
339→                item_type: crate::crypto::bin::BinItemType::File,
340→                name: item_name.clone(),
341→                original_parent_ipns_name: parent_ipns_name,
342→                original_path: parent_path,
343→                deleted_at: SystemTime::now()
344→                    .duration_since(std::time::UNIX_EPOCH)
345→                    .unwrap_or_default()
346→                    .as_millis() as u64,
347→                size: file_size,
348→                mime_type: crate::crypto::bin::guess_mime_type(&item_name).to_string(),
349→                file_pointer: Some(file_pointer),
350→                folder_entry: None,
351→            };
352→
353→            crate::fuse::spawn_bin_entry_publish(
354→                fs.api.clone(),
355→                fs.rt.clone(),
356→                bin_entry,
357→                fs.private_key.to_vec(),
358→                fs.public_key.to_vec(),
359→                fs.publish_coordinator.clone(),
360→            );
361→        }
362→
363→        reply.ok();
364→    }
