599→    /// Remove an empty directory.
600→    pub fn handle_rmdir(
601→        fs: &mut CipherBoxFS,
602→        parent: u64,
603→        name: &OsStr,
604→        reply: ReplyEmpty,
605→    ) {
606→        let name_str = match name.to_str() {
607→            Some(n) => n,
608→            None => {
609→                reply.error(libc::ENOENT);
610→                return;
611→            }
612→        };
613→
614→        let child_ino = match fs.inodes.find_child(parent, name_str) {
615→            Some(ino) => ino,
616→            None => {
617→                reply.error(libc::ENOENT);
618→                return;
619→            }
620→        };
621→
622→        // Capture folder data for bin entry before inode removal
623→        let bin_entry_data = match fs.inodes.get(child_ino) {
624→            Some(inode) => {
625→                match &inode.kind {
626→                    InodeKind::Folder {
627→                        ipns_name,
628→                        encrypted_folder_key,
629→                        ipns_private_key,
630→                        ..
631→                    } => {
632→                        // Check for non-empty folder (POSIX requirement)
633→                        if let Some(ref children) = inode.children {
634→                            if !children.is_empty() {
635→                                reply.error(libc::ENOTEMPTY);
636→                                return;
637→                            }
638→                        }
639→
640→                        let now_ms = SystemTime::now()
641→                            .duration_since(std::time::UNIX_EPOCH)
642→                            .unwrap_or_default()
643→                            .as_millis() as u64;
644→                        let created_ms = inode.attr.crtime
645→                            .duration_since(std::time::UNIX_EPOCH)
646→                            .unwrap_or_default()
647→                            .as_millis() as u64;
648→
649→                        // Build the ECIES-wrapped IPNS private key for the FolderEntry
650→                        let ipns_key_encrypted = if let Some(key) = ipns_private_key {
651→                            match crate::crypto::ecies::wrap_key(key, &fs.public_key) {
652→                                Ok(wrapped) => hex::encode(&wrapped),
653→                                Err(e) => {
654→                                    log::warn!("rmdir: failed to wrap IPNS key for bin entry: {}", e);
655→                                    String::new()
656→                                }
657→                            }
658→                        } else {
659→                            String::new()
660→                        };
661→
662→                        let folder_entry = crate::crypto::folder::FolderEntry {
663→                            id: crate::crypto::bin::generate_uuid_v4(),
664→                            name: inode.name.clone(),
665→                            ipns_name: ipns_name.clone(),
666→                            folder_key_encrypted: encrypted_folder_key.clone(),
667→                            ipns_private_key_encrypted: ipns_key_encrypted,
668→                            created_at: if created_ms > 0 { created_ms } else { now_ms },
669→                            modified_at: now_ms,
670→                        };
671→
672→                        Some((inode.name.clone(), folder_entry))
673→                    }
674→                    _ => {
675→                        reply.error(libc::ENOTDIR);
676→                        return;
677→                    }
678→                }
679→            }
680→            None => {
681→                reply.error(libc::ENOENT);
682→                return;
683→            }
684→        };
685→
686→        log::debug!("rmdir: {} from parent {}", name_str, parent);
687→
688→        fs.inodes.remove(child_ino);
689→
690→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
691→            parent_inode.attr.mtime = SystemTime::now();
692→            parent_inode.attr.ctime = SystemTime::now();
693→        }
694→
695→        if let Err(e) = fs.update_folder_metadata(parent) {
696→            log::error!("Failed to update folder metadata after rmdir: {}", e);
697→        }
698→
699→        // Create bin entry and publish to bin IPNS (fire-and-forget)
700→        if let Some((item_name, folder_entry)) = bin_entry_data {
701→            let parent_ipns_name = fs.inodes.get(parent)
702→                .map(|p| match &p.kind {
703→                    InodeKind::Root { ipns_name, .. } => ipns_name.clone().unwrap_or_default(),
704→                    InodeKind::Folder { ipns_name, .. } => ipns_name.clone(),
705→                    _ => String::new(),
706→                })
707→                .unwrap_or_default();
708→
709→            let parent_path = build_folder_path(fs, parent);
710→
711→            let bin_entry = crate::crypto::bin::BinEntry {
712→                id: crate::crypto::bin::generate_uuid_v4(),
713→                item_type: crate::crypto::bin::BinItemType::Folder,
714→                name: item_name,
715→                original_parent_ipns_name: parent_ipns_name,
716→                original_path: parent_path,
717→                deleted_at: SystemTime::now()
718→                    .duration_since(std::time::UNIX_EPOCH)
719→                    .unwrap_or_default()
720→                    .as_millis() as u64,
721→                size: 0,
722→                mime_type: String::new(),
723→                file_pointer: None,
724→                folder_entry: Some(folder_entry),
725→            };
726→
727→            crate::fuse::spawn_bin_entry_publish(
728→                fs.api.clone(),
729→                fs.rt.clone(),
730→                bin_entry,
731→                fs.private_key.to_vec(),
732→                fs.public_key.to_vec(),
733→                fs.publish_coordinator.clone(),
734→            );
735→        }
736→
737→        reply.ok();
738→    }
