926→    /// Build a human-readable breadcrumb path for a folder inode.
927→    /// Walks parent_ino upward to root, concatenating names with " / ".
928→    /// Example: "My Vault / Documents / Reports"
929→    fn build_folder_path(fs: &CipherBoxFS, folder_ino: u64) -> String {
930→        let mut parts = Vec::new();
931→        let mut current = folder_ino;
932→        for _ in 0..20 { // Safety limit to prevent infinite loops
933→            match fs.inodes.get(current) {
934→                Some(inode) => {
935→                    match &inode.kind {
936→                        InodeKind::Root { .. } => {
937→                            parts.push("My Vault".to_string());
938→                            break;
939→                        }
940→                        _ => {
941→                            parts.push(inode.name.clone());
942→                            current = inode.parent_ino;
943→                        }
944→                    }
945→                }
946→                None => break,
947→            }
948→        }
949→        parts.reverse();
950→        parts.join(" / ")
951→    }
952→}
