3013→+/**
3014→+ * Remove entries from bin metadata and publish the updated metadata.
3015→+ */
3016→+async function removeEntriesFromBin(
3017→+  entryIds: string[],
3018→+  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
3019→+): Promise<void> {
3020→+  const binStore = useBinStore.getState();
3021→+  const idsToRemove = new Set(entryIds);
3022→+  const remainingEntries = binStore.entries.filter((e) => !idsToRemove.has(e.id));
3023→+  const newSeq = binStore.sequenceNumber + 1;
3024→+
3025→+  const metadata: RecycleBinMetadata = {
3026→+    version: 'v1',
3027→+    sequenceNumber: newSeq,
3028→+    entries: remainingEntries,
3029→+  };
3030→+
3031→+  await saveBinMetadata({
3032→+    metadata,
3033→+    userPublicKey: params.userPublicKey,
3034→+    userPrivateKey: params.userPrivateKey,
3035→+  });
