3041→+/**
3042→+ * Cleanup CIDs for a bin entry (unpin from IPFS + update quota).
3043→+ *
3044→+ * Files: resolve file IPNS -> get CID -> unpin
3045→+ * Folders: recursively resolve descendant file CIDs -> unpin all
3046→+ */
3047→+async function cleanupEntryCids(entry: BinEntry): Promise<void> {
3048→+  if (entry.itemType === 'file' && entry.filePointer) {
3049→+    const fileIpnsName = entry.filePointer.fileMetaIpnsName;
3050→+    if (fileIpnsName) {
3051→+      try {
3052→+        const resolved = await resolveIpnsRecord(fileIpnsName);
3053→+        if (resolved?.cid) {
3054→+          // Fetch file metadata to get the actual content CID and size
3055→+          const metaBytes = await fetchFromIpfs(resolved.cid);
3056→+          const metaJson = new TextDecoder().decode(metaBytes);
3057→+          const fileMeta = JSON.parse(metaJson);
3058→+
3059→+          // Unpin the content CID (encrypted file data)
3060→+          if (fileMeta.cid) {
3061→+            await unpinFromIpfs(fileMeta.cid);
3062→+            // Update quota
3063→+            if (fileMeta.size && typeof fileMeta.size === 'number') {
3064→+              useQuotaStore.getState().removeUsage(fileMeta.size);
3065→+            }
3066→+          }
3067→+
3068→+          // Also unpin the metadata CID
3069→+          await unpinFromIpfs(resolved.cid).catch(() => {});
3070→+        }
3071→+      } catch (err) {
3072→+        console.error(`[Bin] CID cleanup failed for file ${entry.name}:`, err);
3073→+      }
3074→+    }
3075→+  } else if (entry.itemType === 'folder' && entry.folderEntry) {
3076→+    // Recursively resolve folder to find all descendant file CIDs
3077→+    await cleanupFolderCids(entry.folderEntry.ipnsName);
3078→+  }
3079→+}
3080→+
3081→+/**
3082→+ * Recursively unpin all CIDs in a folder tree.
3083→+ */
3084→+async function cleanupFolderCids(folderIpnsName: string): Promise<void> {
3085→+  try {
3086→+    const resolved = await resolveIpnsRecord(folderIpnsName);
3087→+    if (!resolved?.cid) return;
3088→+
3089→+    // Try to load folder metadata -- it may be AES-GCM encrypted
3090→+    // We don't have the folder key here, so we check if the folder is
3091→+    // loaded in the store first
3092→+    const folders = useFolderStore.getState().folders;
3093→+    const folderNode = Object.values(folders).find((f) => f.ipnsName === folderIpnsName);
3094→+
3095→+    if (folderNode) {
3096→+      // Folder is loaded -- iterate children
3097→+      for (const child of folderNode.children) {
3098→+        if (child.type === 'file') {
3099→+          const fp = child as FilePointer;
3100→+          if (fp.fileMetaIpnsName) {
3101→+            try {
3102→+              const fileResolved = await resolveIpnsRecord(fp.fileMetaIpnsName);
3103→+              if (fileResolved?.cid) {
3104→+                const metaBytes = await fetchFromIpfs(fileResolved.cid);
3105→+                const metaJson = new TextDecoder().decode(metaBytes);
3106→+                const fileMeta = JSON.parse(metaJson);
3107→+                if (fileMeta.cid) {
3108→+                  await unpinFromIpfs(fileMeta.cid);
3109→+                  if (fileMeta.size && typeof fileMeta.size === 'number') {
3110→+                    useQuotaStore.getState().removeUsage(fileMeta.size);
3111→+                  }
3112→+                }
3113→+                await unpinFromIpfs(fileResolved.cid).catch(() => {});
3114→+              }
3115→+            } catch (err) {
3116→+              console.error(`[Bin] CID cleanup failed for nested file:`, err);
3117→+            }
3118→+          }
3119→+        } else if (child.type === 'folder') {
3120→+          const fe = child as FolderEntry;
3121→+          await cleanupFolderCids(fe.ipnsName);
3122→+        }
3123→+      }
3124→+    }
3125→+
3126→+    // Unpin the folder metadata CID itself
3127→+    await unpinFromIpfs(resolved.cid).catch(() => {});
3128→+  } catch (err) {
3129→+    console.error(`[Bin] Folder CID cleanup failed for ${folderIpnsName}:`, err);
3130→+  }
3131→+}
