    let metadata: bin::RecycleBinMetadata = serde_json::from_str(json).unwrap();
    assert_eq!(metadata.version, "v1");
    assert_eq!(metadata.sequence_number, 2);
    assert_eq!(metadata.entries.len(), 2);
