        confirmLabel: 'Delete Permanently',
        onConfirm: async () => {
          try {
            await permanentDelete(entryId);
            clearSelection();
            setConfirmDialog((prev) => ({ ...prev, open: false }));
          } catch {
            console.error('[Bin] Permanent delete failed');
          }
        },
      });
    },
    [entries, permanentDelete, clearSelection]
  );

