{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2881632984","pull_request_review_id":3886528032,"id":2881632984,"node_id":"PRRC_kwDOQ6DXvM6rwjrY","diff_hunk":"@@ -0,0 +1,538 @@
+/**
+ * BinBrowser -- Recycle bin browser with flat list of deleted items.
+ *
+ * Shows all soft-deleted files and folders in a flat list sorted by deletion date.
+ * Supports restore, permanent delete, batch operations, and Empty Bin.
+ * Auto-purges expired items on mount.
+ */
+
+import { useState, useCallback, useEffect, useRef, useMemo, type MouseEvent } from 'react';
+import type { BinEntry } from '@cipherbox/crypto';
+import { useBin } from '../../hooks/useBin';
+import { BinListItem } from './BinListItem';
+import { BinEmptyState } from './BinEmptyState';
+import { ConfirmDialog } from './ConfirmDialog';
+import '../../styles/bin-browser.css';
+
+type SortField = 'name' | 'deletedAt' | 'size' | 'daysRemaining';
+type SortDirection = 'asc' | 'desc';
+
+export function BinBrowser() {
+  const {
+    entries,
+    isLoading,
+    isLoaded,
+    error,
+    retentionDays,
+    daysRemaining,
+    loadBin,
+    restore,
+    permanentDelete,
+    emptyAll,
+    restoreMultiple,
+    permanentDeleteMultiple,
+    isLoading: isOperating,
+  } = useBin();
+
+  // Sort state
+  const [sortField, setSortField] = useState<SortField>('deletedAt');
+  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');
+
+  // Selection state
+  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
+  const lastSelectedIdRef = useRef<string | null>(null);
+  const contextMenuRef = useRef<HTMLDivElement>(null);
+
+  // Confirmation dialog state
+  const [confirmDialog, setConfirmDialog] = useState<{
+    open: boolean;
+    title: string;
+    message: string;
+    confirmLabel: string;
+    onConfirm: () => void;
+  }>({ open: false, title: '', message: '', confirmLabel: '', onConfirm: () => {} });
+
+  // Context menu state
+  const [contextMenu, setContextMenu] = useState<{
+    visible: boolean;
+    x: number;
+    y: number;
+    entry: BinEntry | null;
+  }>({ visible: false, x: 0, y: 0, entry: null });
+
+  // Load bin on mount
+  useEffect(() => {
+    void loadBin();
+  }, [loadBin]);
+
+  // Prune stale selectedIds when entries change
+  const entryIds = useMemo(() => new Set(entries.map((e) => e.id)), [entries]);
+  useEffect(() => {
+    setSelectedIds((prev) => {
+      if (prev.size === 0) return prev;
+      const pruned = new Set([...prev].filter((id) => entryIds.has(id)));
+      if (pruned.size === prev.size) return prev;
+      return pruned;
+    });
+  }, [entryIds]);
+
+  // Sort entries
+  const sortedEntries = useMemo(() => {
+    const sorted = [...entries].sort((a, b) => {
+      let cmp = 0;
+      switch (sortField) {
+        case 'name':
+          cmp = a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
+          break;
+        case 'deletedAt':
+          cmp = a.deletedAt - b.deletedAt;
+          break;
+        case 'size':
+          cmp = a.size - b.size;
+          break;
+        case 'daysRemaining':
+          cmp = daysRemaining(a) - daysRemaining(b);
+          break;
+      }
+      return sortDirection === 'asc' ? cmp : -cmp;
+    });
+    return sorted;
+  }, [entries, sortField, sortDirection, daysRemaining]);
+
+  // Toggle sort column
+  const handleSortClick = useCallback(
+    (field: SortField) => {
+      if (sortField === field) {
+        setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
+      } else {
+        setSortField(field);
+        setSortDirection(field === 'name' ? 'asc' : 'desc');
+      }
+    },
+    [sortField]
+  );
+
+  // Sort indicator
+  const sortIndicator = (field: SortField) => {
+    if (sortField !== field) return '';
+    return sortDirection === 'asc' ? ' ^' : ' v';
+  };
+
+  // Selection handlers
+  const handleSelect = useCallback(
+    (entryId: string, event: { ctrlKey: boolean; shiftKey: boolean; metaKey: boolean }) => {
+      const isCtrl = event.ctrlKey || event.metaKey;
+      const isShift = event.shiftKey;
+
+      if (isShift && lastSelectedIdRef.current) {
+        const ids = sortedEntries.map((e) => e.id);
+        const startIdx = ids.indexOf(lastSelectedIdRef.current);
+        const endIdx = ids.indexOf(entryId);
+        if (startIdx !== -1 && endIdx !== -1) {
+          const rangeStart = Math.min(startIdx, endIdx);
+          const rangeEnd = Math.max(startIdx, endIdx);
+          const rangeIds = ids.slice(rangeStart, rangeEnd + 1);
+          setSelectedIds((prev) => {
+            const next = new Set(prev);
+            for (const id of rangeIds) next.add(id);
+            return next;
+          });
+          lastSelectedIdRef.current = entryId;
+        } else {
+          // Stale anchor — fall back to selecting the clicked row
+          setSelectedIds(new Set([entryId]));
+          lastSelectedIdRef.current = entryId;
+        }
+      } else if (isCtrl) {
+        setSelectedIds((prev) => {
+          const next = new Set(prev);
+          if (next.has(entryId)) next.delete(entryId);
+          else next.add(entryId);
+          return next;
+        });
+        lastSelectedIdRef.current = entryId;
+      } else {
+        setSelectedIds(new Set([entryId]));
+        lastSelectedIdRef.current = entryId;
+      }
+    },
+    [sortedEntries]
+  );
+
+  const clearSelection = useCallback(() => {
+    setSelectedIds(new Set());
+    lastSelectedIdRef.current = null;
+  }, []);
+
+  // Context menu handlers
+  const handleContextMenu = useCallback(
+    (event: MouseEvent, entry: BinEntry) => {
+      event.preventDefault();
+      // If right-clicked entry is not selected, select only that entry
+      if (!selectedIds.has(entry.id)) {
+        setSelectedIds(new Set([entry.id]));
+        lastSelectedIdRef.current = entry.id;
+      }
+      setContextMenu({ visible: true, x: event.clientX, y: event.clientY, entry });
+    },
+    [selectedIds]
+  );
+
+  const hideContextMenu = useCallback(() => {
+    setContextMenu({ visible: false, x: 0, y: 0, entry: null });
+  }, []);
+
+  // Close context menu on click outside or escape
+  useEffect(() => {
+    if (!contextMenu.visible) return;
+
+    const handleClickOutside = (event: globalThis.MouseEvent) => {
+      if (contextMenuRef.current && !contextMenuRef.current.contains(event.target as Node)) {
+        hideContextMenu();
+      }
+    };
+    const handleKeyDown = (e: KeyboardEvent) => {
+      if (e.key === 'Escape') hideContextMenu();
+    };
+
+    document.addEventListener('mousedown', handleClickOutside, true);
+    document.addEventListener('keydown', handleKeyDown);
+    return () => {
+      document.removeEventListener('mousedown', handleClickOutside, true);
+      document.removeEventListener('keydown', handleKeyDown);
+    };
+  }, [contextMenu.visible, hideContextMenu]);
+
+  // Action handlers
+  const handleRestore = useCallback(
+    async (entryId: string) => {
+      try {
+        await restore(entryId);
+        clearSelection();
+      } catch (err) {
+        console.error('Restore failed:', err);
+      }","path":"apps/web/src/components/file-browser/BinBrowser.tsx","commit_id":"6f3575d478fb018e626be54e6b2812e144c77ff4","original_commit_id":"6f3575d478fb018e626be54e6b2812e144c77ff4","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Fixed in 66694ab — all catch blocks in BinBrowser now use bare `catch` (no `err` binding) with static log messages like `[Bin] Restore failed` instead of logging the raw error object.","created_at":"2026-03-04T03:44:06Z","updated_at":"2026-03-04T03:44:06Z","html_url":"https://github.com/FSM1/cipher-box/pull/262#discussion_r2881632984","pull_request_url":"https://api.github.com/repos/FSM1/cipher-box/pulls/262","_links":{"self":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2881632984"},"html":{"href":"https://github.com/FSM1/cipher-box/pull/262#discussion_r2881632984"},"pull_request":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/262"}},"reactions":{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2881632984/reactions","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"confused":0,"heart":0,"rocket":0,"eyes":0},"start_line":null,"original_start_line":212,"start_side":"RIGHT","line":null,"original_line":214,"side":"RIGHT","in_reply_to_id":2881582863,"author_association":"OWNER","original_position":214,"position":1,"subject_type":"line"}

