+    const auth = useAuthStore.getState();
+    if (!auth.vaultKeypair) throw new Error('Not authenticated');
+
+    setState({ isLoading: true, error: null });
+    try {
+      for (const entryId of entryIds) {
+        await restoreFromBin({
+          entryId,
+          userPublicKey: auth.vaultKeypair.publicKey,
+          userPrivateKey: auth.vaultKeypair.privateKey,
+        });
+      }
+      setState({ isLoading: false, error: null });
+    } catch (err) {
+      const error = err instanceof Error ? err.message : 'Failed to restore items';
+      setState({ isLoading: false, error });
+      throw err;
+    }
+  }, []);
+
+  /**
+   * Permanently delete multiple bin entries.
+   */
+  const permanentDeleteMultiple = useCallback(async (entryIds: string[]) => {
+    const auth = useAuthStore.getState();
+    if (!auth.vaultKeypair) throw new Error('Not authenticated');
+
+    setState({ isLoading: true, error: null });
+    try {
+      for (const entryId of entryIds) {
+        await permanentlyDelete({
+          entryId,
+          userPublicKey: auth.vaultKeypair.publicKey,
+          userPrivateKey: auth.vaultKeypair.privateKey,
+        });
+      }
+      setState({ isLoading: false, error: null });
+    } catch (err) {
+      const error = err instanceof Error ? err.message : 'Failed to permanently delete items';
+      setState({ isLoading: false, error });
+      throw err;
+    }
+  }, []);","path":"apps/web/src/hooks/useBin.ts","commit_id":"66694ab204625862f38a78d864f304a42767884f","original_commit_id":"6f3575d478fb018e626be54e6b2812e144c77ff4","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Fixed in 66694ab — added `restoreFromBinBatch` and `permanentlyDeleteBatch` service methods that perform all folder restores/CID cleanups first, then publish bin metadata once at the end. `useBin.ts` now uses these batch methods instead of looping with per-item calls.","created_at":"2026-03-04T03:44:08Z","updated_at":"2026-03-04T03:44:08Z","html_url":"https://github.com/FSM1/cipher-box/pull/262#discussion_r2881633030","pull_request_url":"https://api.github.com/repos/FSM1/cipher-box/pulls/262","_links":{"self":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2881633030"},"html":{"href":"https://github.com/FSM1/cipher-box/pull/262#discussion_r2881633030"},"pull_request":{"href":"https://api.github.com/repos/FSM1/cipher-box/pulls/262"}},"reactions":{"url":"https://api.github.com/repos/FSM1/cipher-box/pulls/comments/2881633030/reactions","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"confused":0,