//! Write operations for macOS FUSE filesystem.
//!
//! Contains handler logic for: write, create, setattr, rename, unlink, rmdir, mkdir.

#[cfg(feature = "fuse")]
pub(crate) mod implementation {
    use fuser::{
        ReplyAttr, ReplyCreate, ReplyEmpty, ReplyEntry, ReplyWrite,
    };
    use std::ffi::OsStr;
    use std::sync::atomic::Ordering;
    use std::time::SystemTime;

    use crate::fuse::CipherBoxFS;
    use crate::fuse::file_handle::OpenFileHandle;
    use crate::fuse::helpers::is_platform_special;
    use crate::fuse::inode::{FileAttrs, InodeData, InodeKind};
    use crate::fuse::operations::implementation::{
        ttl_for_is_dir, current_uid, current_gid, FILE_TTL, DIR_TTL,
    };

    /// Set file attributes (handles truncate via size parameter).
    pub fn handle_setattr(
        fs: &mut CipherBoxFS,
        ino: u64,
        size: Option<u64>,
        fh: Option<u64>,
        reply: ReplyAttr,
    ) {
        log::debug!("setattr: ino={} size={:?} fh={:?}", ino, size, fh);
        if let Some(new_size) = size {
            if let Some(fh_id) = fh {
                if let Some(handle) = fs.open_files.get_mut(&fh_id) {
                    if handle.temp_path.is_some() {
                        if let Err(e) = handle.truncate(new_size) {
                            log::error!("Truncate failed for ino {}: {}", ino, e);
                            reply.error(libc::EIO);
                            return;
                        }
                        handle.dirty = true;
                    }
                }
            } else {
                // No explicit fh -- find open writable handle for this inode
                let matching_fh: Option<u64> = fs.open_files.iter()
                    .find(|(_, h)| h.ino == ino && h.temp_path.is_some())
                    .map(|(id, _)| *id);
                if let Some(fh_id) = matching_fh {
                    if let Some(handle) = fs.open_files.get_mut(&fh_id) {
                        if let Err(e) = handle.truncate(new_size) {
                            log::error!("Truncate (no-fh) failed for ino {}: {}", ino, e);
                            reply.error(libc::EIO);
                            return;
                        }
                        handle.dirty = true;
                    }
                }
            }

            if let Some(inode) = fs.inodes.get_mut(ino) {
                inode.attr.size = new_size;
                inode.attr.blocks = (new_size + 511) / 512;
                inode.attr.mtime = SystemTime::now();

                if new_size == 0 {
                    inode.write_generation += 1;
                    if let InodeKind::File { size: ref mut s, cid: ref mut c, .. } = inode.kind {
                        *s = 0;
                        *c = String::new();
                    }
                } else {
                    if let InodeKind::File { size: ref mut s, .. } = inode.kind {
                        *s = new_size;
                    }
                }

                reply.attr(&ttl_for_is_dir(inode.attr.is_dir), &inode.attr.to_fuse_attr(current_uid(), current_gid()));
                return;
            }
        }

        if let Some(inode) = fs.inodes.get(ino) {
            reply.attr(&ttl_for_is_dir(inode.attr.is_dir), &inode.attr.to_fuse_attr(current_uid(), current_gid()));
        } else {
            reply.error(libc::ENOENT);
        }
    }

    /// Write data to an open file.
    pub fn handle_write(
        fs: &mut CipherBoxFS,
        ino: u64,
        fh: u64,
        offset: i64,
        data: &[u8],
        reply: ReplyWrite,
    ) {
        let handle = match fs.open_files.get_mut(&fh) {
            Some(h) => h,
            None => {
                reply.error(libc::EBADF);
                return;
            }
        };

        match handle.write_at(offset, data) {
            Ok(written) => {
                let new_end = offset as u64 + data.len() as u64;
                if let Some(inode) = fs.inodes.get_mut(ino) {
                    if new_end > inode.attr.size {
                        inode.attr.size = new_end;
                        inode.attr.blocks = (new_end + 511) / 512;
                    }
                    inode.attr.mtime = SystemTime::now();
                }
                reply.written(written as u32);
            }
            Err(e) => {
                log::error!("Write failed for ino {} fh {}: {}", ino, fh, e);
                reply.error(libc::EIO);
            }
        }
    }

    /// Create a new file in a directory.
    pub fn handle_create(
        fs: &mut CipherBoxFS,
        parent: u64,
        name: &OsStr,
        _flags: i32,
        reply: ReplyCreate,
    ) {
        let name_str = match name.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::EINVAL);
                return;
            }
        };

        if is_platform_special(name_str) {
            reply.error(libc::EACCES);
            return;
        }

        let parent_exists = fs.inodes.get(parent).map(|inode| {
            matches!(inode.kind, InodeKind::Root { .. } | InodeKind::Folder { .. })
        });
        if parent_exists != Some(true) {
            reply.error(libc::ENOENT);
            return;
        }

        let ino = fs.inodes.allocate_ino();
        let now = SystemTime::now();

        let attr = FileAttrs {
            ino,
            size: 0,
            blocks: 0,
            atime: now,
            mtime: now,
            ctime: now,
            crtime: now,
            is_dir: false,
            perm: 0o644,
            nlink: 1,
        };
        let fuse_attr = attr.to_fuse_attr(current_uid(), current_gid());

        // Generate random Ed25519 IPNS keypair for this file
        let signing_key = ed25519_dalek::SigningKey::generate(&mut rand::rngs::OsRng);
        let verifying_key = signing_key.verifying_key();
        let file_ipns_private_key = signing_key.to_bytes().to_vec();
        let file_ipns_public_key_bytes: [u8; 32] = verifying_key.to_bytes();
        let file_ipns_name = match crate::crypto::ipns::derive_ipns_name(&file_ipns_public_key_bytes) {
            Ok(name) => name,
            Err(e) => {
                log::error!("create: IPNS name derivation from random keypair failed: {}", e);
                reply.error(libc::EIO);
                return;
            }
        };

        let ipns_key_encrypted_hex = match crate::crypto::ecies::wrap_key(&file_ipns_private_key, &fs.public_key) {
            Ok(wrapped) => Some(hex::encode(&wrapped)),
            Err(e) => {
                log::error!("create: failed to ECIES-wrap IPNS key: {}. Cannot proceed without wrapped key.", e);
                reply.error(libc::EIO);
                return;
            }
        };

        let inode = InodeData {
            ino,
            parent_ino: parent,
            name: name_str.to_string(),
            kind: InodeKind::File {
                cid: String::new(),
                encrypted_file_key: String::new(),
                iv: String::new(),
                size: 0,
                encryption_mode: "GCM".to_string(),
                file_meta_ipns_name: Some(file_ipns_name),
                file_meta_resolved: true,
                file_ipns_private_key: Some(zeroize::Zeroizing::new(file_ipns_private_key)),
                file_ipns_key_encrypted_hex: ipns_key_encrypted_hex,
                versions: None,
            },
            attr,
            children: None,
            write_generation: 0,
        };

        fs.inodes.insert(inode);

        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
            if let Some(ref mut children) = parent_inode.children {
                children.push(ino);
            }
            parent_inode.attr.mtime = SystemTime::now();
            parent_inode.attr.ctime = SystemTime::now();
        }

        let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
        match OpenFileHandle::new_write(ino, &fs.temp_dir, None) {
            Ok(handle) => {
                fs.open_files.insert(fh, handle);
            }
            Err(e) => {
                log::error!("Failed to create temp file for new file: {}", e);
                fs.inodes.remove(ino);
                if let Some(parent_inode) = fs.inodes.get_mut(parent) {
                    if let Some(ref mut children) = parent_inode.children {
                        children.retain(|&child| child != ino);
                    }
                }
                reply.error(libc::EIO);
                return;
            }
        }

        fs.mutated_folders.insert(parent, std::time::Instant::now());

        log::debug!("create: {} in parent {} -> ino {} fh {}", name_str, parent, ino, fh);
        reply.created(&FILE_TTL, &fuse_attr, 0, fh, 0);
    }

    /// Delete a file from a directory.
    pub fn handle_unlink(
        fs: &mut CipherBoxFS,
        parent: u64,
        name: &OsStr,
        reply: ReplyEmpty,
    ) {
        let name_str = match name.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        let child_ino = match fs.inodes.find_child(parent, name_str) {
            Some(ino) => ino,
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        // Capture data for bin entry before inode removal
        let bin_entry_data = match fs.inodes.get(child_ino) {
            Some(inode) => match &inode.kind {
                InodeKind::File {
                    file_meta_ipns_name,
                    file_ipns_key_encrypted_hex,
                    size,
                    ..
                } => {
                    let now_ms = SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis() as u64;
                    let created_ms = inode.attr.crtime
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis() as u64;

                    let meta_ipns = match file_meta_ipns_name {
                        Some(name) if !name.is_empty() => name.clone(),
                        _ => {
                            log::error!("unlink: missing file_meta_ipns_name for ino {}", child_ino);
                            reply.error(libc::EIO);
                            return;
                        }
                    };

                    let file_pointer = crate::crypto::folder::FilePointer {
                        id: crate::crypto::utils::generate_uuid_v4(),
                        name: inode.name.clone(),
                        file_meta_ipns_name: meta_ipns,
                        ipns_private_key_encrypted: file_ipns_key_encrypted_hex.clone(),
                        created_at: if created_ms > 0 { created_ms } else { now_ms },
                        modified_at: now_ms,
                    };

                    Some((inode.name.clone(), *size, file_pointer))
                }
                _ => {
                    reply.error(libc::EISDIR);
                    return;
                }
            },
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        log::debug!("unlink: {} from parent {}", name_str, parent);

        let now = SystemTime::now();

        fs.inodes.remove(child_ino);

        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
            parent_inode.attr.mtime = now;
            parent_inode.attr.ctime = now;
        }

        if let Err(e) = fs.update_folder_metadata(parent) {
            log::error!("Failed to update folder metadata after unlink: {}", e);
        }

        // Create bin entry and publish to bin IPNS (fire-and-forget)
        if let Some((item_name, file_size, file_pointer)) = bin_entry_data {
            let parent_ipns_name = fs.inodes.get(parent)
                .map(|p| match &p.kind {
                    InodeKind::Root { ipns_name, .. } => ipns_name.clone().unwrap_or_default(),
                    InodeKind::Folder { ipns_name, .. } => ipns_name.clone(),
                    _ => String::new(),
                })
                .unwrap_or_default();

            let parent_path = build_folder_path(fs, parent);

            let bin_entry = crate::crypto::bin::BinEntry {
                id: crate::crypto::utils::generate_uuid_v4(),
                item_type: crate::crypto::bin::BinItemType::File,
                name: item_name.clone(),
                original_parent_ipns_name: parent_ipns_name,
                original_path: parent_path,
                deleted_at: now
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_millis() as u64,
                size: file_size,
                mime_type: crate::crypto::utils::mime_from_extension(&item_name).to_string(),
                file_pointer: Some(file_pointer),
                folder_entry: None,
            };

            crate::fuse::spawn_bin_entry_publish(
                fs.api.clone(),
                fs.rt.clone(),
                bin_entry,
                fs.private_key.to_vec(),
                fs.public_key.to_vec(),
                fs.publish_coordinator.clone(),
            );
        }

        reply.ok();
    }

    /// Create a new directory.
    pub fn handle_mkdir(
        fs: &mut CipherBoxFS,
        parent: u64,
        name: &OsStr,
        reply: ReplyEntry,
    ) {
        let name_str = match name.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::EINVAL);
                return;
            }
        };

        if is_platform_special(name_str) {
            reply.error(libc::EACCES);
            return;
        }

        let parent_exists = fs.inodes.get(parent).map(|inode| {
            matches!(inode.kind, InodeKind::Root { .. } | InodeKind::Folder { .. })
        });
        if parent_exists != Some(true) {
            reply.error(libc::ENOENT);
            return;
        }

        log::debug!("mkdir: {} in parent {}", name_str, parent);

        let result = (|| -> Result<fuser::FileAttr, String> {
            let folder_key = crate::crypto::utils::generate_file_key();

            let (ipns_public_key, ipns_private_key) =
                crate::crypto::ed25519::generate_ed25519_keypair();

            let ipns_pub_arr: [u8; 32] = ipns_public_key.clone().try_into()
                .map_err(|_| "Invalid IPNS public key length".to_string())?;
            let ipns_name = crate::crypto::ipns::derive_ipns_name(&ipns_pub_arr)
                .map_err(|e| format!("Failed to derive IPNS name: {}", e))?;

            let wrapped_folder_key = crate::crypto::ecies::wrap_key(
                &folder_key, &fs.public_key,
            )
            .map_err(|e| format!("Folder key wrapping failed: {}", e))?;
            let encrypted_folder_key_hex = hex::encode(&wrapped_folder_key);

            let ino = fs.inodes.allocate_ino();
            let now = SystemTime::now();

            let attr = FileAttrs {
                ino,
                size: 0,
                blocks: 0,
                atime: now,
                mtime: now,
                ctime: now,
                crtime: now,
                is_dir: true,
                perm: 0o755,
                nlink: 2,
            };
            let fuse_attr = attr.to_fuse_attr(current_uid(), current_gid());

            let inode = InodeData {
                ino,
                parent_ino: parent,
                name: name_str.to_string(),
                kind: InodeKind::Folder {
                    ipns_name: ipns_name.clone(),
                    encrypted_folder_key: encrypted_folder_key_hex,
                    folder_key: zeroize::Zeroizing::new(folder_key.to_vec()),
                    ipns_private_key: Some(zeroize::Zeroizing::new(ipns_private_key.clone())),
                    children_loaded: true,
                },
                attr,
                children: Some(vec![]),
                write_generation: 0,
            };

            fs.inodes.insert(inode);

            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
                if let Some(ref mut children) = parent_inode.children {
                    children.push(ino);
                }
                parent_inode.attr.mtime = SystemTime::now();
                parent_inode.attr.ctime = SystemTime::now();
            }

            let metadata = crate::crypto::folder::FolderMetadata {
                version: "v2".to_string(),
                children: vec![],
            };

            let json_bytes = crate::fuse::encrypt_metadata_to_json(
                &metadata, &folder_key,
            )?;

            let encrypted_ipns_for_tee = if let Some(ref tee_key) = fs.tee_public_key {
                let wrapped = crate::crypto::ecies::wrap_key(&ipns_private_key, tee_key)
                    .map_err(|e| format!("TEE key wrapping failed: {}", e))?;
                Some(hex::encode(&wrapped))
            } else {
                None
            };
            let tee_key_epoch = fs.tee_key_epoch;

            let (parent_metadata, parent_folder_key, parent_ipns_key, parent_ipns_name, parent_old_cid) =
                fs.build_folder_metadata(parent)?;

            let api = fs.api.clone();
            let rt = fs.rt.clone();
            let ipns_name_clone = ipns_name.clone();
            let coordinator = fs.publish_coordinator.clone();

            std::thread::spawn(move || {
                let result = rt.block_on(async {
                    let initial_cid = crate::api::ipfs::upload_content(
                        &api, &json_bytes,
                    ).await?;

                    let ipns_key_arr: [u8; 32] = ipns_private_key.try_into()
                        .map_err(|_| "Invalid IPNS key length".to_string())?;
                    let value = format!("/ipfs/{}", initial_cid);
                    let record = crate::crypto::ipns::create_ipns_record(
                        &ipns_key_arr, &value, 0, 86_400_000,
                    ).map_err(|e| format!("IPNS record creation failed: {}", e))?;
                    let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
                        .map_err(|e| format!("IPNS marshal failed: {}", e))?;

                    use base64::Engine;
                    let record_b64 = base64::engine::general_purpose::STANDARD
                        .encode(&marshaled);

                    // New folder initial publish: sequence 0, no conflict check needed
                    let req = crate::api::ipns::IpnsPublishRequest {
                        ipns_name: ipns_name_clone.clone(),
                        record: record_b64,
                        metadata_cid: initial_cid,
                        encrypted_ipns_private_key: encrypted_ipns_for_tee,
                        key_epoch: tee_key_epoch,
                        expected_sequence_number: None,
                    };
                    match crate::api::ipns::publish_ipns(&api, &req).await? {
                        crate::api::ipns::PublishResult::Success => {
                            coordinator.record_publish(&ipns_name_clone, 0);
                            log::info!("New folder IPNS published: {}", ipns_name_clone);
                        }
                        crate::api::ipns::PublishResult::Conflict { .. } => {
                            // Sequence 0 should never conflict -- log and continue
                            log::warn!("Unexpected conflict on new folder IPNS publish for {}", ipns_name_clone);
                        }
                    }

                    let lock = coordinator.get_lock(&parent_ipns_name);
                    let _guard = lock.lock().await;

                    let parent_json = crate::fuse::encrypt_metadata_to_json(
                        &parent_metadata, &parent_folder_key,
                    )?;

                    let seq = coordinator.resolve_sequence(&api, &parent_ipns_name).await?;

                    let parent_meta_cid = crate::api::ipfs::upload_content(
                        &api, &parent_json,
                    ).await?;

                    let parent_key_arr: [u8; 32] = parent_ipns_key.try_into()
                        .map_err(|_| "Invalid parent IPNS key length".to_string())?;
                    let new_seq = seq + 1;
                    let parent_value = format!("/ipfs/{}", parent_meta_cid);
                    let parent_record = crate::crypto::ipns::create_ipns_record(
                        &parent_key_arr, &parent_value, new_seq, 86_400_000,
                    ).map_err(|e| format!("Parent IPNS record failed: {}", e))?;
                    let parent_marshaled = crate::crypto::ipns::marshal_ipns_record(
                        &parent_record,
                    ).map_err(|e| format!("Parent IPNS marshal failed: {}", e))?;
                    let parent_record_b64 = base64::engine::general_purpose::STANDARD
                        .encode(&parent_marshaled);

                    // Parent folder publish after mkdir includes conflict detection.
                    // On conflict, log a warning -- the debounced publish queue will
                    // retry the parent metadata on the next cycle.
                    // TODO: Add full re-fetch+merge+retry for parent mkdir publish (v2).
                    let parent_req = crate::api::ipns::IpnsPublishRequest {
                        ipns_name: parent_ipns_name.clone(),
                        record: parent_record_b64,
                        metadata_cid: parent_meta_cid,
                        encrypted_ipns_private_key: None,
                        key_epoch: None,
                        expected_sequence_number: Some(seq.to_string()),
                    };
                    match crate::api::ipns::publish_ipns(&api, &parent_req).await? {
                        crate::api::ipns::PublishResult::Success => {
                            coordinator.record_publish(&parent_ipns_name, new_seq);
                            // Only unpin old CID on successful publish
                            if let Some(old) = parent_old_cid {
                                let _ = crate::api::ipfs::unpin_content(&api, &old).await;
                            }
                            log::info!("Parent metadata published after mkdir");
                        }
                        crate::api::ipns::PublishResult::Conflict { current_sequence_number } => {
                            log::warn!(
                                "Conflict on parent publish after mkdir (expected seq {}, server has {}). \
                                Debounced publish will retry.",
                                seq, current_sequence_number
                            );
                            // Do not record_publish or unpin -- let the next debounced publish pick up fresh seq
                        }
                    }
                    Ok::<(), String>(())
                });

                if let Err(e) = result {
                    log::error!("Background mkdir publish failed: {}", e);
                }
            });

            Ok(fuse_attr)
        })();

        match result {
            Ok(fuse_attr) => {
                reply.entry(&DIR_TTL, &fuse_attr, 0);
            }
            Err(e) => {
                log::error!("mkdir failed: {}", e);
                reply.error(libc::EIO);
            }
        }
    }

    /// Remove an empty directory.
    pub fn handle_rmdir(
        fs: &mut CipherBoxFS,
        parent: u64,
        name: &OsStr,
        reply: ReplyEmpty,
    ) {
        let name_str = match name.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        let child_ino = match fs.inodes.find_child(parent, name_str) {
            Some(ino) => ino,
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        // Capture folder data for bin entry before inode removal
        let bin_entry_data = match fs.inodes.get(child_ino) {
            Some(inode) => {
                match &inode.kind {
                    InodeKind::Folder {
                        ipns_name,
                        encrypted_folder_key,
                        ipns_private_key,
                        ..
                    } => {
                        // Check for non-empty folder (POSIX requirement)
                        if let Some(ref children) = inode.children {
                            if !children.is_empty() {
                                reply.error(libc::ENOTEMPTY);
                                return;
                            }
                        }

                        let now_ms = SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap_or_default()
                            .as_millis() as u64;
                        let created_ms = inode.attr.crtime
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap_or_default()
                            .as_millis() as u64;

                        // Build the ECIES-wrapped IPNS private key for the FolderEntry
                        let ipns_key_encrypted = if let Some(key) = ipns_private_key {
                            match crate::crypto::ecies::wrap_key(key, &fs.public_key) {
                                Ok(wrapped) => hex::encode(&wrapped),
                                Err(e) => {
                                    log::warn!("rmdir: failed to wrap IPNS key for bin entry: {}", e);
                                    String::new()
                                }
                            }
                        } else {
                            String::new()
                        };

                        let folder_entry = crate::crypto::folder::FolderEntry {
                            id: crate::crypto::utils::generate_uuid_v4(),
                            name: inode.name.clone(),
                            ipns_name: ipns_name.clone(),
                            folder_key_encrypted: encrypted_folder_key.clone(),
                            ipns_private_key_encrypted: ipns_key_encrypted,
                            created_at: if created_ms > 0 { created_ms } else { now_ms },
                            modified_at: now_ms,
                        };

                        Some((inode.name.clone(), folder_entry))
                    }
                    _ => {
                        reply.error(libc::ENOTDIR);
                        return;
                    }
                }
            }
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        log::debug!("rmdir: {} from parent {}", name_str, parent);

        let now = SystemTime::now();

        fs.inodes.remove(child_ino);

        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
            parent_inode.attr.mtime = now;
            parent_inode.attr.ctime = now;
        }

        if let Err(e) = fs.update_folder_metadata(parent) {
            log::error!("Failed to update folder metadata after rmdir: {}", e);
        }

        // Create bin entry and publish to bin IPNS (fire-and-forget)
        if let Some((item_name, folder_entry)) = bin_entry_data {
            let parent_ipns_name = fs.inodes.get(parent)
                .map(|p| match &p.kind {
                    InodeKind::Root { ipns_name, .. } => ipns_name.clone().unwrap_or_default(),
                    InodeKind::Folder { ipns_name, .. } => ipns_name.clone(),
                    _ => String::new(),
                })
                .unwrap_or_default();

            let parent_path = build_folder_path(fs, parent);

            let bin_entry = crate::crypto::bin::BinEntry {
                id: crate::crypto::utils::generate_uuid_v4(),
                item_type: crate::crypto::bin::BinItemType::Folder,
                name: item_name,
                original_parent_ipns_name: parent_ipns_name,
                original_path: parent_path,
                deleted_at: now
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_millis() as u64,
                size: 0,
                mime_type: String::new(),
                file_pointer: None,
                folder_entry: Some(folder_entry),
            };

            crate::fuse::spawn_bin_entry_publish(
                fs.api.clone(),
                fs.rt.clone(),
                bin_entry,
                fs.private_key.to_vec(),
                fs.public_key.to_vec(),
                fs.publish_coordinator.clone(),
            );
        }

        reply.ok();
    }

    /// Rename or move a file/folder.
    pub fn handle_rename(
        fs: &mut CipherBoxFS,
        parent: u64,
        name: &OsStr,
        newparent: u64,
        newname: &OsStr,
        reply: ReplyEmpty,
    ) {
        log::debug!(
            "rename: {:?} (parent {}) -> {:?} (parent {})",
            name, parent, newname, newparent,
        );
        let name_str = match name.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::EINVAL);
                return;
            }
        };
        let newname_str = match newname.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::EINVAL);
                return;
            }
        };

        // Find source inode (with FUSE-T truncated name fallback)
        let (source_ino, actual_name) = match fs.inodes.find_child(parent, name_str) {
            Some(ino) => (ino, name_str.to_string()),
            None => {
                let parent_inode = match fs.inodes.get(parent) {
                    Some(i) => i,
                    None => {
                        reply.error(libc::ENOENT);
                        return;
                    }
                };
                let children = parent_inode.children.clone().unwrap_or_default();
                let mut matches: Vec<(u64, String)> = Vec::new();
                for &child_ino in &children {
                    if let Some(child) = fs.inodes.get(child_ino) {
                        if is_platform_special(&child.name) {
                            continue;
                        }
                        if child.name.ends_with(name_str) && child.name.len() > name_str.len() {
                            matches.push((child_ino, child.name.clone()));
                        }
                    }
                }
                if matches.len() == 1 {
                    log::debug!(
                        "rename suffix-match: truncated {:?} matched full name {:?}",
                        name_str, matches[0].1
                    );
                    (matches[0].0, matches[0].1.clone())
                } else {
                    log::debug!(
                        "rename failed: {:?} not found (suffix matches: {})",
                        name_str, matches.len()
                    );
                    reply.error(libc::ENOENT);
                    return;
                }
            }
        };

        let name_str = &actual_name;

        log::debug!(
            "rename: {} (ino {}) in parent {} -> {} in parent {}",
            name_str, source_ino, parent, newname_str, newparent,
        );

        // If destination exists, handle replacement
        if let Some(dest_ino) = fs.inodes.find_child(newparent, newname_str) {
            // Self-replace (rename "a" to "a" in same dir): no-op
            if dest_ino == source_ino {
                reply.ok();
                return;
            }

            if let Some(dest_inode) = fs.inodes.get(dest_ino) {
                // Validate kind compatibility (POSIX: can't replace file with dir or vice versa)
                let source_is_dir = fs.inodes.get(source_ino)
                    .map(|i| matches!(i.kind, InodeKind::Root { .. } | InodeKind::Folder { .. }))
                    .unwrap_or(false);
                let dest_is_dir = matches!(
                    dest_inode.kind,
                    InodeKind::Root { .. } | InodeKind::Folder { .. }
                );
                if source_is_dir && !dest_is_dir {
                    reply.error(libc::ENOTDIR);
                    return;
                }
                if !source_is_dir && dest_is_dir {
                    reply.error(libc::EISDIR);
                    return;
                }

                match &dest_inode.kind {
                    InodeKind::Folder { .. } => {
                        if let Some(ref children) = dest_inode.children {
                            if !children.is_empty() {
                                reply.error(libc::ENOTEMPTY);
                                return;
                            }
                        }
                    }
                    InodeKind::File { cid, .. } => {
                        if !cid.is_empty() {
                            let cid_clone = cid.clone();
                            let api = fs.api.clone();
                            fs.rt.spawn(async move {
                                let _ = crate::api::ipfs::unpin_content(
                                    &api, &cid_clone,
                                ).await;
                            });
                        }
                    }
                    _ => {}
                }
            }
            fs.inodes.remove(dest_ino);
        }

        // Remove source from old parent's name index (NFC-normalized)
        {
            use unicode_normalization::UnicodeNormalization;
            let nfc_key: String = name_str.nfc().collect();
            fs.inodes.name_to_ino.remove(&(parent, nfc_key));
        }

        // Update the source inode's name and parent
        if let Some(inode) = fs.inodes.get_mut(source_ino) {
            inode.name = newname_str.to_string();
            inode.parent_ino = newparent;
            inode.attr.ctime = SystemTime::now();
        }

        // Update the name lookup index for the new location (NFC-normalized)
        {
            use unicode_normalization::UnicodeNormalization;
            let nfc_key: String = newname_str.nfc().collect();
            fs.inodes.name_to_ino.insert(
                (newparent, nfc_key),
                source_ino,
            );
        }

        if parent != newparent {
            if let Some(old_parent) = fs.inodes.get_mut(parent) {
                if let Some(ref mut children) = old_parent.children {
                    children.retain(|&c| c != source_ino);
                }
                old_parent.attr.mtime = SystemTime::now();
                old_parent.attr.ctime = SystemTime::now();
            }
            if let Some(new_parent) = fs.inodes.get_mut(newparent) {
                if let Some(ref mut children) = new_parent.children {
                    children.push(source_ino);
                }
                new_parent.attr.mtime = SystemTime::now();
                new_parent.attr.ctime = SystemTime::now();
            }

            if let Err(e) = fs.update_folder_metadata(parent) {
                log::error!("Failed to update old parent metadata after rename: {}", e);
            }
            if let Err(e) = fs.update_folder_metadata(newparent) {
                log::error!("Failed to update new parent metadata after rename: {}", e);
            }
        } else {
            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
                parent_inode.attr.mtime = SystemTime::now();
                parent_inode.attr.ctime = SystemTime::now();
            }
            if let Err(e) = fs.update_folder_metadata(parent) {
                log::error!("Failed to update parent metadata after rename: {}", e);
            }
        }

        reply.ok();
    }

    /// Build a human-readable breadcrumb path for a folder inode.
    /// Walks parent_ino upward to root, concatenating names with " / ".
    /// Example: "My Vault / Documents / Reports"
    fn build_folder_path(fs: &CipherBoxFS, folder_ino: u64) -> String {
        let mut parts = Vec::new();
        let mut current = folder_ino;
        for _ in 0..20 { // Safety limit to prevent infinite loops
            match fs.inodes.get(current) {
                Some(inode) => {
                    match &inode.kind {
                        InodeKind::Root { .. } => {
                            parts.push("My Vault".to_string());
                            break;
                        }
                        _ => {
                            parts.push(inode.name.clone());
                            current = inode.parent_ino;
                        }
                    }
                }
                None => break,
            }
        }
        parts.reverse();
        parts.join(" / ")
    }
}

import { useState, useCallback } from 'react';
import { useFolderStore } from '../stores/folder.store';
import { useVaultStore } from '../stores/vault.store';
import { useAuthStore } from '../stores/auth.store';
import * as folderService from '../services/folder.service';
import { reWrapForRecipients } from '../services/share.service';
import { addManyToBin } from '../services/bin.service';
import type { FolderNode } from '../stores/folder.store';
import type { FolderEntry, FolderChild } from '@cipherbox/crypto';
import {
  MAX_FOLDER_DEPTH,
  getRootFolderState,
  resyncFolder,
  withConflictRetry,
} from './folder-helpers';
import type { FolderOperationState } from './folder-helpers';

/**
 * Build a breadcrumb-style path string for a folder by walking up the tree.
 * e.g., "My Vault / Documents / Reports"
 */
function buildFolderPath(folderId: string): string {
  const folders = useFolderStore.getState().folders;
  const parts: string[] = [];
  let currentId: string | null = folderId;

  while (currentId !== null) {
    const folder: FolderNode | undefined = folders[currentId];
    if (!folder) break;
    parts.unshift(folder.name);
    currentId = folder.parentId;
  }

  return parts.length > 0 ? parts.join(' / ') : 'My Vault';
}

/**
 * React hook for folder CRUD operations (create, rename, move, delete).
 *
 * Returns loading/error state and operation callbacks.
 */
export function useFolderMutations() {
  const [state, setState] = useState<FolderOperationState>({
    isLoading: false,
    error: null,
  });

  /**
   * Create a new folder.
   *
   * @param name - Folder name
   * @param parentId - Parent folder ID (null for root, or folder UUID)
   * @returns Created folder entry
   * @throws Error if depth limit exceeded or creation fails
   */
  const handleCreate = useCallback(
    async (name: string, parentId: string | null): Promise<FolderEntry> => {
      setState({ isLoading: true, error: null });
      try {
        const folders = useFolderStore.getState().folders;
        const vault = useVaultStore.getState();
        const auth = useAuthStore.getState();

        // Validate depth limit before creating (FOLD-03)
        const parentDepth = folderService.getDepth(parentId, folders);
        if (parentDepth >= MAX_FOLDER_DEPTH) {
          throw new Error(`Cannot create folder: maximum depth of ${MAX_FOLDER_DEPTH} exceeded`);
        }

        // Get user's ECIES keypair for vault cryptographic operations (public + private keys stored in memory after login)
        // The public key is used here for key wrapping; the private key remains client-side for decryption operations.
        if (!auth.vaultKeypair) {
          throw new Error('No ECIES keypair available - please log in again');
        }
        const userPublicKey = auth.vaultKeypair.publicKey;

        // Create the folder (generates keys, wraps with user public key, TEE-encrypts IPNS key)
        const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
          await folderService.createFolder({
            parentFolderId: parentId,
            name,
            userPublicKey,
            folders,
          });

        // Get parent folder state
        const parentFolder =
          parentId && folders[parentId] ? folders[parentId] : getRootFolderState(vault, folders);

        if (!parentFolder) {
          throw new Error('Parent folder not found or vault not initialized');
        }

        // Update parent folder metadata and publish IPNS (with conflict retry)
        const performParentUpdate = async () => {
          const freshState = useFolderStore.getState();
          const freshParent =
            parentId && freshState.folders[parentId]
              ? freshState.folders[parentId]
              : getRootFolderState(useVaultStore.getState(), freshState.folders);
          if (!freshParent) throw new Error('Parent folder not found');
          const freshChildren = [...freshParent.children, folder];
          const { newSequenceNumber } = await folderService.updateFolderMetadata({
            folderId: freshParent.id,
            children: freshChildren,
            folderKey: freshParent.folderKey,
            ipnsPrivateKey: freshParent.ipnsPrivateKey,
            ipnsName: freshParent.ipnsName,
            sequenceNumber: freshParent.sequenceNumber,
          });
          return { children: freshChildren, newSequenceNumber };
        };

        const parentResult = await withConflictRetry(performParentUpdate, () =>
          resyncFolder(parentFolder.ipnsName, parentFolder.id)
        );

        // First publish for the new folder's own IPNS record with TEE-encrypted key
        // This sends encryptedIpnsPrivateKey to backend for TEE republish enrollment
        const { newSequenceNumber: newFolderSequence } = await folderService.updateFolderMetadata({
          folderId: folder.id,
          children: [],
          folderKey,
          ipnsPrivateKey,
          ipnsName: folder.ipnsName,
          sequenceNumber: 0n,
          encryptedIpnsPrivateKey,
          keyEpoch,
        });

        // Update local state - add new folder to tree and persist sequence
        useFolderStore.getState().updateFolderChildren(parentFolder.id, parentResult.children);
        useFolderStore
          .getState()
          .updateFolderSequence(parentFolder.id, parentResult.newSequenceNumber);

        // Also add the new folder node to the store (with its decrypted keys)
        const newFolderNode: FolderNode = {
          id: folder.id,
          name: folder.name,
          ipnsName: folder.ipnsName,
          parentId: parentFolder.id,
          children: [],
          isLoaded: true,
          isLoading: false,
          sequenceNumber: newFolderSequence,
          folderKey,
          ipnsPrivateKey,
        };
        useFolderStore.getState().setFolder(newFolderNode);

        // Post-create: re-wrap new subfolder key for share recipients (fire-and-forget)
        reWrapForRecipients({
          folderIpnsName: parentFolder.ipnsName,
          folders: useFolderStore.getState().folders,
          currentFolderId: parentFolder.id,
          newItems: [{ keyType: 'folder', itemId: folder.id, plaintextKey: folderKey }],
        }).catch((err) => {
          console.warn('[share] Post-create subfolder re-wrapping failed:', err);
        });

        setState({ isLoading: false, error: null });
        return folder;
      } catch (err) {
        const error = err instanceof Error ? err.message : 'Failed to create folder';
        setState({ isLoading: false, error });
        throw err;
      }
    },
    []
  );

  /**
   * Rename a file or folder.
   *
   * @param itemId - ID of item to rename
   * @param itemType - 'file' or 'folder'
   * @param newName - New name
   * @param parentId - Parent folder ID
   */
  const handleRename = useCallback(
    async (
      itemId: string,
      itemType: 'file' | 'folder',
      newName: string,
      parentId: string
    ): Promise<void> => {
      setState({ isLoading: true, error: null });
      try {
        const getParentFolder = () => {
          const freshState = useFolderStore.getState();
          return parentId === 'root'
            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
            : freshState.folders[parentId];
        };

        const parentFolder = getParentFolder();
        if (!parentFolder) throw new Error('Parent folder not found');

        const performRename = async (): Promise<{ newSequenceNumber: bigint }> => {
          const freshParent = getParentFolder();
          if (!freshParent) throw new Error('Parent folder not found');
          if (itemType === 'folder') {
            return await folderService.renameFolder({
              folderId: itemId,
              newName,
              parentFolderState: freshParent,
            });
          } else {
            return await folderService.renameFile({
              fileId: itemId,
              newName,
              parentFolderState: freshParent,
            });
          }
        };

        const renameResult = await withConflictRetry(performRename, () =>
          resyncFolder(parentFolder.ipnsName, parentFolder.id)
        );

        if (itemType === 'folder') {
          // Update local folder state name
          useFolderStore.getState().updateFolderName(itemId, newName);
        }

        // Update parent's children with new name using fresh state
        const freshParent = getParentFolder();
        if (freshParent) {
          const updatedChildren = freshParent.children.map((child) => {
            if (child.id === itemId) {
              return { ...child, name: newName, modifiedAt: Date.now() };
            }
            return child;
          });
          useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
        }

        // Persist the new sequence number so subsequent operations use the correct value
        useFolderStore.getState().updateFolderSequence(parentId, renameResult.newSequenceNumber);

        setState({ isLoading: false, error: null });
      } catch (err) {
        const error = err instanceof Error ? err.message : 'Failed to rename';
        setState({ isLoading: false, error });
        throw err;
      }
    },
    []
  );

  /**
   * Move a file or folder to a different parent.
   *
   * @param itemId - ID of item to move
   * @param itemType - 'file' or 'folder'
   * @param sourceParentId - Current parent folder ID
   * @param destParentId - Destination parent folder ID
   */
  const handleMove = useCallback(
    async (
      itemId: string,
      itemType: 'file' | 'folder',
      sourceParentId: string,
      destParentId: string
    ): Promise<void> => {
      setState({ isLoading: true, error: null });
      try {
        const getSourceFolder = () => {
          const freshState = useFolderStore.getState();
          return sourceParentId === 'root'
            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
            : freshState.folders[sourceParentId];
        };

        const getDestFolder = () => {
          const freshState = useFolderStore.getState();
          return destParentId === 'root'
            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
            : freshState.folders[destParentId];
        };

        const sourceFolder = getSourceFolder();
        const destFolder = getDestFolder();
        if (!sourceFolder || !destFolder) {
          throw new Error('Source or destination folder not found');
        }

        const performMove = async (): Promise<{
          destSequenceNumber: bigint;
          sourceSequenceNumber: bigint;
        }> => {
          const freshSource = getSourceFolder();
          const freshDest = getDestFolder();
          if (!freshSource || !freshDest) throw new Error('Source or destination folder not found');
          const folders = useFolderStore.getState().folders;
          if (itemType === 'folder') {
            return await folderService.moveFolder({
              folderId: itemId,
              sourceFolderState: freshSource,
              destFolderState: freshDest,
              folders,
            });
          } else {
            return await folderService.moveFile({
              fileId: itemId,
              sourceFolderState: freshSource,
              destFolderState: freshDest,
            });
          }
        };

        const moveResult = await withConflictRetry(performMove, async () => {
          await Promise.all([
            resyncFolder(sourceFolder.ipnsName, sourceFolder.id),
            sourceFolder.id !== destFolder.id
              ? resyncFolder(destFolder.ipnsName, destFolder.id)
              : Promise.resolve(),
          ]);
        });

        // Save the moved item BEFORE updating source children (otherwise it's already gone)
        const freshSourceBeforeUpdate = getSourceFolder();
        const movedItem = freshSourceBeforeUpdate?.children.find((c) => c.id === itemId);

        if (itemType === 'folder') {
          // Update the moved folder's parentId in local state
          const freshFolders = useFolderStore.getState().folders;
          const movedFolder = freshFolders[itemId];
          if (movedFolder) {
            useFolderStore.getState().setFolder({
              ...movedFolder,
              parentId: destParentId,
            });
          }
        }

        // Update source folder's children (remove item)
        if (freshSourceBeforeUpdate) {
          const updatedSourceChildren = freshSourceBeforeUpdate.children.filter(
            (c) => c.id !== itemId
          );
          useFolderStore.getState().updateFolderChildren(sourceParentId, updatedSourceChildren);
        }

        // Update dest folder's children (add item)
        const freshDest = getDestFolder();
        if (movedItem && freshDest) {
          const updatedDestChildren = [
            ...freshDest.children,
            { ...movedItem, modifiedAt: Date.now() },
          ];
          useFolderStore.getState().updateFolderChildren(destParentId, updatedDestChildren);
        }

        // Persist the new sequence numbers so subsequent operations use the correct values
        useFolderStore.getState().updateFolderSequence(destParentId, moveResult.destSequenceNumber);
        useFolderStore
          .getState()
          .updateFolderSequence(sourceParentId, moveResult.sourceSequenceNumber);

        setState({ isLoading: false, error: null });
      } catch (err) {
        const error = err instanceof Error ? err.message : 'Failed to move';
        setState({ isLoading: false, error });
        throw err;
      }
    },
    []
  );

  /**
   * Move multiple files/folders to a destination in a single batch.
   *
   * Uses add-before-remove pattern. Publishes IPNS once for the destination
   * and once for the source (2 total), regardless of how many items are moved.
   *
   * @param items - Array of { id, type } to move
   * @param sourceParentId - Current parent folder ID (all items must share the same parent)
   * @param destParentId - Destination parent folder ID
   */
  const handleMoveItems = useCallback(
    async (
      items: Array<{ id: string; type: 'file' | 'folder' }>,
      sourceParentId: string,
      destParentId: string
    ): Promise<void> => {
      setState({ isLoading: true, error: null });
      try {
        const getSourceFolder = () => {
          const freshState = useFolderStore.getState();
          return sourceParentId === 'root'
            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
            : freshState.folders[sourceParentId];
        };
        const getDestFolder = () => {
          const freshState = useFolderStore.getState();
          return destParentId === 'root'
            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
            : freshState.folders[destParentId];
        };

        const sourceFolder = getSourceFolder();
        const destFolder = getDestFolder();

        if (!sourceFolder || !destFolder) {
          throw new Error('Source or destination folder not found');
        }

        const itemIds = new Set(items.map((i) => i.id));
        const now = Date.now();

        // Validate batch move preconditions against current folder state.
        // Must be called before each attempt (initial + retry after resync)
        // because concurrent changes may introduce name collisions or depth violations.
        const validateBatchMove = () => {
          const currentSource = getSourceFolder();
          const currentDest = getDestFolder();
          if (!currentSource || !currentDest) {
            throw new Error('Source or destination folder not found');
          }

          const currentMovedChildren = currentSource.children.filter((c) => itemIds.has(c.id));
          if (currentMovedChildren.length !== itemIds.size) {
            throw new Error(
              'One or more selected items no longer exist. Please refresh and retry.'
            );
          }
          const batchNames = new Set<string>();
          for (const child of currentMovedChildren) {
            // Intra-batch duplicate name check
            if (batchNames.has(child.name)) {
              throw new Error(`Multiple selected items share the name "${child.name}"`);
            }
            batchNames.add(child.name);

            // Name collision check against destination
            const nameExists = currentDest.children.some((c) => c.name === child.name);
            if (nameExists) {
              throw new Error(`An item named "${child.name}" already exists in the destination`);
            }

            if (child.type === 'folder') {
              // Prevent moving folder into itself or descendant
              const folders = useFolderStore.getState().folders;
              if (folderService.isDescendantOf(currentDest.id, child.id, folders)) {
                throw new Error(`Cannot move "${child.name}" into itself or its subfolder`);
              }

              // Depth limit check
              const destDepth = folderService.getDepth(currentDest.id, folders);
              const subtreeDepth = folderService.calculateSubtreeDepth(child.id, folders);
              if (destDepth + 1 + subtreeDepth > MAX_FOLDER_DEPTH) {
                throw new Error(
                  `Cannot move "${child.name}": would exceed maximum folder depth of ${MAX_FOLDER_DEPTH}`
                );
              }
            }
          }
        };

        validateBatchMove();

        const performBatchMove = async (): Promise<{
          destSeq: bigint;
          sourceSeq: bigint;
          destChildren: FolderNode['children'];
          sourceChildren: FolderNode['children'];
        }> => {
          const freshSource = getSourceFolder();
          const freshDest = getDestFolder();
          if (!freshSource || !freshDest) throw new Error('Source or destination folder not found');

          // Rebuild moved children from fresh source state
          const freshMoved = freshSource.children.filter((c) => itemIds.has(c.id));
          if (freshMoved.length !== itemIds.size) {
            throw new Error(
              'One or more selected items no longer exist. Please refresh and retry.'
            );
          }

          // ADD all to destination FIRST (add-before-remove pattern)
          const destChildren = [
            ...freshDest.children,
            ...freshMoved.map((c) => ({ ...c, modifiedAt: now })),
          ];

          const { newSequenceNumber: destSeq } = await folderService.updateFolderMetadata({
            folderId: freshDest.id,
            children: destChildren,
            folderKey: freshDest.folderKey,
            ipnsPrivateKey: freshDest.ipnsPrivateKey,
            ipnsName: freshDest.ipnsName,
            sequenceNumber: freshDest.sequenceNumber,
          });

          // REMOVE all from source AFTER destination confirmed
          const sourceChildren = freshSource.children.filter((c) => !itemIds.has(c.id));

          const { newSequenceNumber: sourceSeq } = await folderService.updateFolderMetadata({
            folderId: freshSource.id,
            children: sourceChildren,
            folderKey: freshSource.folderKey,
            ipnsPrivateKey: freshSource.ipnsPrivateKey,
            ipnsName: freshSource.ipnsName,
            // Re-read sequence in case source === dest parent was updated above
            sequenceNumber: freshSource.id === freshDest.id ? destSeq : freshSource.sequenceNumber,
          });

          return { destSeq, sourceSeq, destChildren, sourceChildren };
        };

        const result = await withConflictRetry(
          performBatchMove,
          async () => {
            await Promise.all([
              resyncFolder(sourceFolder.ipnsName, sourceFolder.id),
              sourceFolder.id !== destFolder.id
                ? resyncFolder(destFolder.ipnsName, destFolder.id)
                : Promise.resolve(),
            ]);
          },
          validateBatchMove
        );

        // Update local state
        const store = useFolderStore.getState();
        store.updateFolderChildren(sourceParentId, result.sourceChildren);
        store.updateFolderChildren(destParentId, result.destChildren);
        store.updateFolderSequence(destParentId, result.destSeq);
        store.updateFolderSequence(sourceParentId, result.sourceSeq);

        for (const item of items) {
          if (item.type === 'folder') {
            const movedFolder = useFolderStore.getState().folders[item.id];
            if (movedFolder) {
              store.setFolder({ ...movedFolder, parentId: destParentId });
            }
          }
        }

        setState({ isLoading: false, error: null });
      } catch (err) {
        const error = err instanceof Error ? err.message : 'Failed to move items';
        setState({ isLoading: false, error });
        throw err;
      }
    },
    []
  );

  /**
   * Delete a file or folder.
   *
   * @param itemId - ID of item to delete
   * @param itemType - 'file' or 'folder'
   * @param parentId - Parent folder ID
   */
  const handleDelete = useCallback(
    async (itemId: string, itemType: 'file' | 'folder', parentId: string): Promise<void> => {
      setState({ isLoading: true, error: null });
      try {
        const getParentFolder = () => {
          const freshState = useFolderStore.getState();
          return parentId === 'root'
            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
            : freshState.folders[parentId];
        };

        const parentFolder = getParentFolder();
        if (!parentFolder) throw new Error('Parent folder not found');

        const performDelete = async (): Promise<{
          newSequenceNumber: bigint;
          removedChild: FolderChild;
        }> => {
          const freshParent = getParentFolder();
          if (!freshParent) throw new Error('Parent folder not found');
          if (itemType === 'folder') {
            const folders = useFolderStore.getState().folders;
            const { newSequenceNumber, removedChild } = await folderService.deleteFolder({
              folderId: itemId,
              parentFolderState: freshParent,
              getFolderState: (id) => folders[id],
            });
            return { newSequenceNumber, removedChild };
          } else {
            const { newSequenceNumber, removedChild } = await folderService.deleteFileFromFolder({
              fileId: itemId,
              parentFolderState: freshParent,
            });
            return { newSequenceNumber, removedChild };
          }
        };

        const deleteResult = await withConflictRetry(performDelete, () =>
          resyncFolder(parentFolder.ipnsName, parentFolder.id)
        );

        if (itemType === 'folder') {
          // Remove folder and all loaded descendants from local state
          const store = useFolderStore.getState();
          const removeRecursive = (folderId: string) => {
            const node = store.folders[folderId];
            if (node) {
              for (const child of node.children) {
                if (child.type === 'folder') removeRecursive(child.id);
              }
            }
            store.removeFolder(folderId);
          };
          removeRecursive(itemId);
        }

        // Update parent's children (remove item) using fresh state
        const freshParent = getParentFolder();
        if (freshParent) {
          const updatedChildren = freshParent.children.filter((c) => c.id !== itemId);
          useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
        }

        // Persist the new sequence number so subsequent operations use the correct value
        useFolderStore.getState().updateFolderSequence(parentId, deleteResult.newSequenceNumber);

        // Fire-and-forget: add deleted item to recycle bin (CIDs stay pinned for recovery)
        const auth = useAuthStore.getState();
        if (auth.vaultKeypair) {
          void addManyToBin({
            items: [deleteResult.removedChild],
            parentIpnsName: parentFolder.ipnsName,
            parentPath: buildFolderPath(parentId),
            userPublicKey: auth.vaultKeypair.publicKey,
            userPrivateKey: auth.vaultKeypair.privateKey,
          }).catch(() => {
            console.error('[Delete] Failed to add to bin (non-blocking)');
          });
        }

        setState({ isLoading: false, error: null });
      } catch (err) {
        const error = err instanceof Error ? err.message : 'Failed to delete';
        setState({ isLoading: false, error });
        throw err;
      }
    },
    []
  );

  /**
   * Delete multiple files/folders in a single IPNS publish.
   *
   * Removes all items from parent's children array, collects CIDs to unpin,
   * then publishes metadata and IPNS once for the entire batch.
   *
   * @param items - Array of { id, type } to delete
   * @param parentId - Parent folder ID (all items must share the same parent)
   */
  const handleDeleteItems = useCallback(
    async (
      items: Array<{ id: string; type: 'file' | 'folder' }>,
      parentId: string
    ): Promise<void> => {
      setState({ isLoading: true, error: null });
      try {
        const getParentFolder = () => {
          const freshState = useFolderStore.getState();
          return parentId === 'root'
            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
            : freshState.folders[parentId];
        };

        const parentFolder = getParentFolder();
        if (!parentFolder) throw new Error('Parent folder not found');

        const itemIds = new Set(items.map((i) => i.id));

        // Collect nested folder IDs to remove from store
        // In v2, file children are FilePointers (no inline CID). File IPNS/TEE
        // enrollments will expire naturally (24h IPNS lifetime). Phase 14 adds cleanup.
        const folderIdsToRemove: string[] = [];

        const collectFolderIds = (folderId: string) => {
          folderIdsToRemove.push(folderId);
          const folders = useFolderStore.getState().folders;
          const folder = folders[folderId];
          if (!folder) return;
          for (const child of folder.children) {
            if (child.type === 'folder') {
              collectFolderIds(child.id);
            }
          }
        };

        for (const item of items) {
          if (item.type === 'folder') {
            collectFolderIds(item.id);
          }
        }

        // Snapshot the items to be removed before batch delete
        // (needed for addToBin after successful deletion)
        let removedChildren: FolderChild[] = [];

        const performBatchDelete = async (): Promise<{
          updatedChildren: typeof parentFolder.children;
          newSequenceNumber: bigint;
        }> => {
          const freshParent = getParentFolder();
          if (!freshParent) throw new Error('Parent folder not found');

          // Capture removed children before filtering
          removedChildren = freshParent.children.filter((c) => itemIds.has(c.id));

          // Remove all items from parent's children in one pass
          const updatedChildren = freshParent.children.filter((c) => !itemIds.has(c.id));

          // Single IPNS publish for the entire batch
          const { newSequenceNumber } = await folderService.updateFolderMetadata({
            folderId: freshParent.id,
            children: updatedChildren,
            folderKey: freshParent.folderKey,
            ipnsPrivateKey: freshParent.ipnsPrivateKey,
            ipnsName: freshParent.ipnsName,
            sequenceNumber: freshParent.sequenceNumber,
          });

          return { updatedChildren, newSequenceNumber };
        };

        const { updatedChildren, newSequenceNumber } = await withConflictRetry(
          performBatchDelete,
          () => resyncFolder(parentFolder.ipnsName, parentFolder.id)
        );

        // Update local state -- remove all nested folders from store
        const store = useFolderStore.getState();
        store.updateFolderChildren(parentId, updatedChildren);
        store.updateFolderSequence(parentId, newSequenceNumber);
        for (const folderId of folderIdsToRemove) {
          store.removeFolder(folderId);
        }

        // Fire-and-forget: add all deleted items to recycle bin (single IPNS publish)
        const auth = useAuthStore.getState();
        if (auth.vaultKeypair && removedChildren.length > 0) {
          const parentPath = buildFolderPath(parentId);
          void addManyToBin({
            items: removedChildren,
            parentIpnsName: parentFolder.ipnsName,
            parentPath,
            userPublicKey: auth.vaultKeypair.publicKey,
            userPrivateKey: auth.vaultKeypair.privateKey,
          }).catch(() => {
            console.error('[Delete] Failed to add batch to bin (non-blocking)');
          });
        }

        setState({ isLoading: false, error: null });
      } catch (err) {
        const error = err instanceof Error ? err.message : 'Failed to delete items';
        setState({ isLoading: false, error });
        throw err;
      }
    },
    []
  );

  return {
    ...state,
    createFolder: handleCreate,
    renameItem: handleRename,
    moveItem: handleMove,
    moveItems: handleMoveItems,
    deleteItem: handleDelete,
    deleteItems: handleDeleteItems,
  };
}

