+          await cleanupFolderCids(fe.ipnsName);
+        }
+      }
+    }","path":"apps/web/src/services/bin.service.ts","commit_id":"2058a4952b76a328babdff683a47e3de3c2139db","original_commit_id":"66694ab204625862f38a78d864f304a42767884f","user":{"login":"FSM1","id":12774278,"node_id":"MDQ6VXNlcjEyNzc0Mjc4","avatar_url":"https://avatars.githubusercontent.com/u/12774278?v=4","gravatar_id":"","url":"https://api.github.com/users/FSM1","html_url":"https://github.com/FSM1","followers_url":"https://api.github.com/users/FSM1/followers","following_url":"https://api.github.com/users/FSM1/following{/other_user}","gists_url":"https://api.github.com/users/FSM1/gists{/gist_id}","starred_url":"https://api.github.com/users/FSM1/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/FSM1/subscriptions","organizations_url":"https://api.github.com/users/FSM1/orgs","repos_url":"https://api.github.com/users/FSM1/repos","events_url":"https://api.github.com/users/FSM1/events{/privacy}","received_events_url":"https://api.github.com/users/FSM1/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"This is a known limitation of the zero-knowledge architecture. Folder metadata is encrypted with the parent's folderKey, which isn't available in the `cleanupFolderCids` context (we only have the IPNS name). Loading it would require fetching the encrypted metadata and then decrypting it, which requires the folderKey from the parent's encrypted metadata — creating a recursive key resolution problem.

